internal object DuaAm1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("ከእንቅልፍ መንቃት", "ምስጋና ሁሉ ከሞት በኋላ (ከእንቅልፍ) ሕይወትን ለሰጠን ለአላህ ይግባው፣ መመለሻውም ወደ እርሱ ነው።", "ከእንቅልፍ ወዲያውኑ ሲነቁ አላህን ለማመስገን ይነገራል።", "ነቢዩ ﷺ ሲነቁ ይህን ያነቡ ነበር — ቀኑን በምስጋናና በመጨረሻው ቀን መታሰቢያ መጀመር።"),
        "dua_leaving_home" to DuaText("ከቤት መውጣት", "በአላህ ስም፤ በአላህ ላይ እመካለሁ። ኃይልም ብርታትም ከአላህ በቀር የለም።", "ከቤት ሲወጡ አላህ እንዲጠብቅ ይነገራል።", "መላእክት፡ 'ተመርተሃል፣ ተንከባከበህ፣ ተጠብቀሃል' ይላሉ፣ ሰይጣንም ይርቃል።"),
        "dua_anxiety_distress" to DuaText("የጭንቀትና የሐዘን ጸሎት", "አላህ ሆይ፣ ከጭንቀትና ከሐዘን፣ ከድክመትና ከስንፍና፣ ከንፉግነትና ከፈሪነት፣ ከዕዳ ሸክምና ከሰዎች ጭቆና በአንተ እጠበቃለሁ።", "በሐዘን፣ በጭንቀት፣ በዕዳ ወይም በአእምሮ ጫና ጊዜ።", "ነቢዩ ﷺ ይህን ደጋግመው ያደርጉ ነበር — ከሐዘን፣ ከስንፍናና ከዕዳ መጠበቂያ።"),
        "dua_sayyidul_istighfar" to DuaText("የምህረት ጸሎቶች ሁሉ ራስ", "አላህ ሆይ፣ አንተ ጌታዬ ነህ፤ ከአንተ በቀር በእውነት የሚመለክ የለም። አንተ ፈጠርከኝ፣ እኔም ባሪያህ ነኝ፣ በቻልኩት መጠን በቃል ኪዳንህና በተስፋህ እጸናለሁ። ካደረግሁት ክፋት በአንተ እጠበቃለሁ። ጸጋህን በእኔ ላይ አምናለሁ፣ ኃጢአቴንም አምናለሁ፣ ስለዚህ ይቅር በለኝ፣ ከአንተ በቀር ኃጢአትን የሚምር የለምና።", "ጠዋትና ማታ ይነገራል — ነቢዩ ﷺ ያስተማሩት ምርጥ የንስሐ ጸሎት።", "ማታ በእምነት ያነበበውና በዚያች ሌሊት የሞተ ገነት ይገባል፤ ጠዋትም እንዲሁ።"),
        "dua_parents" to DuaText("ለወላጆች ጸሎት", "ጌታዬ ሆይ፣ ትንሽ ሳለሁ እንዳሳደጉኝ ሁለቱንም ማራቸው።", "ለወላጆች እንክብካቤ ምላሽ የሚደረግ የቁርአን ጸሎት።", "አላህ ራሱ ለወላጆቻችን ይህን ጸሎት እንድናደርግ አዞናል።"),
        "dua_entering_mosque" to DuaText("መስጊድ መግባት", "አላህ ሆይ፣ የምህረትህን በሮች ክፈትልኝ።", "በቀኝ እግር መስጊድ ሲገቡ ይነገራል።", "ነቢዩ ﷺ ይህን ጸሎት መስጊድ ለመግባት አስተምረዋል።"),
        "dua_morning_asbahna" to DuaText("የጠዋት መታሰቢያ", "ጠዋትን ገባን፣ ንግስናውም ሁሉ የአላህ ነው፣ ምስጋናውም ሁሉ የአላህ ነው። ብቸኛ ተጋሪ የሌለው ከአላህ በቀር የሚመለክ የለም። ንግስናውና ምስጋናው ለእርሱ ነው፣ በሁሉም ነገር ላይ ቻይ ነው።", "ጠዋት የሚነገር የሱና ጸሎት።", "ቀኑ በአላህ ንግስናና አንድነት እውቅና ይጀምራል።"),
        "dua_evening_amsayna" to DuaText("የማታ መታሰቢያ", "ማታን ገባን፣ ንግስናውም ሁሉ የአላህ ነው፣ ምስጋናውም ሁሉ የአላህ ነው። ብቸኛ ተጋሪ የሌለው ከአላህ በቀር የሚመለክ የለም። ንግስናውና ምስጋናው ለእርሱ ነው፣ በሁሉም ነገር ላይ ቻይ ነው።", "ማታ የሚነገር የሱና ጸሎት።", "ሌሊቱ በአላህ ንግስናና አንድነት እውቅና ይጀምራል።"),
        "dua_before_sleep" to DuaText("ከመተኛት በፊት", "አላህ ሆይ፣ በስምህ እሞታለሁ (እተኛለሁ) እኖራለሁም (እነቃለሁ)።", "አልጋ ላይ ከተኙ በኋላ ይነገራል።", "ነቢዩ ﷺ ከመተኛታቸው በፊት ይህን ያነቡ ነበር።"),
        "dua_travel" to DuaText("የጉዞ ጸሎት", "ይህን ላስገዛልን ጌታ ጥራት ይገባው፤ እኛ ራሳችን ልናደርገው ባልቻልንም ነበር፤ ወደ ጌታችንም በእርግጥ ተመላሾች ነን።", "ተሽከርካሪ ላይ ከተቀመጡና ሦስት ጊዜ አላሁ አክበር ካሉ በኋላ ይነገራል።", "ለጥበቃና ለበረከት የሚደረግ የሱና የጉዞ ጸሎት።"),
        "dua_ayatul_kursi" to DuaText("ከሶላት በኋላ አያቱል ኩርሲ", "አላህ — ከእርሱ በቀር በእውነት የሚመለክ የለም፣ ሕያው፣ ሁሉን አስተናባሪ። እንቅልፍም እንቅልፍ አይይዘውም። በሰማያትና በምድር ያለው ሁሉ የእርሱ ነው። ያለ ፈቃዱ በእርሱ ዘንድ ማን ሊያማልድ ይችላል? በፊታቸውና ከኋላቸው ያለውን ያውቃል። ከዕውቀቱ የፈለገውን በቀር ምንም አያውቁም። መንበሩ ሰማያትንና ምድርን ይሸፍናል፣ መጠበቃቸውም አያደክመውም። እርሱ ልዑልና ታላቅ ነው።", "ከግዴታ ሶላት ሁሉ በኋላና ከመተኛት በፊት ይነገራል።", "ከግዴታ ሶላት በኋላ ያነበበውን ከገነት የሚከለክለው ሞት ብቻ ነው፤ ከመተኛት በፊት እስከ ጠዋት ይጠበቃል።"),
        "dua_hasbunallah" to DuaText("አላህ ይበቃናል", "አላህ ይበቃናል፣ እርሱም በላጭ ጠባቂ ነው።", "ጠላትን ሲፈሩ ወይም ትልቅ አደጋ ሲያጋጥም።", "ነቢዩ ኢብራሂም (ዐ.ሰ) በእሳት ውስጥ ሲጣሉ ይህን ተናገሩ፣ ነቢዩም ﷺ በአደጋ ጊዜ ይህን ይናገሩ ነበር።"),
        "dua_entering_home" to DuaText("ቤት መግባት", "በአላህ ስም (ቤት እገባለሁ)።", "ቤት ሲገቡ የአላህን ስም መጥራትና ሰላምታ መስጠት።", "አላህ በመግቢያና በምግብ ጊዜ ሲታሰብ ሰይጣን፡ 'እዚህ መቆያም እራትም የለም' ይላል።"),
        "dua_yunus" to DuaText("የነቢዩ ዩኑስ (ዐ.ሰ) ጸሎት", "ከአንተ በቀር በእውነት የሚመለክ የለም፤ ጥራት ይገባህ፤ በእውነት እኔ ከበደለኞች ነበርኩ።", "የነቢዩ ዩኑስ በዓሣው ሆድ ውስጥ የተናገሩት ጸሎት — ለማንኛውም ችግር።", "ማንኛውም ሙስሊም በማንኛውም ጉዳይ ላይ ይህን ጸሎት ቢያደርግ አላህ ይመልስለታል።"),
        "dua_karb" to DuaText("የከባድ ችግር ጸሎት", "ከአላህ በቀር በእውነት የሚመለክ የለም፣ ታላቁ፣ ታጋሹ። ከአላህ በቀር በእውነት የሚመለክ የለም፣ የታላቁ ዙፋን ጌታ። ከአላህ በቀር በእውነት የሚመለክ የለም፣ የሰማያት ጌታ፣ የምድር ጌታ፣ የክቡር ዙፋንም ጌታ።", "በከባድ ችግርና መከራ ጊዜ ይነገራል።", "ነቢዩ ﷺ በችግር ጊዜ ይህን ይናገሩ ነበር።"),
    )
}
